import{_ as t,o as r,c as n,ag as s}from"./chunks/framework.CukOUUOK.js";const u=JSON.parse('{"title":"占位的工会：形式垄断、财政依附与「人民」的统计在场","description":"平台经济中的工会既未\\"替代\\"组织，也未被组织\\"替代\\"，而是占据了一个位置——位置被填满，功能未被履行。以《工会法》第十二条、第四十二条、第四十三条为据，论证形式垄断与财政依附如何共同挤出对抗功能，并提出\\"名册化悖论\\"：清点得越清楚，越不必被召集。","frontmatter":{"title":"占位的工会：形式垄断、财政依附与「人民」的统计在场","categories":"政治思想史","tags":["劳动与经济","制度","权力","社会心理"],"description":"平台经济中的工会既未\\"替代\\"组织，也未被组织\\"替代\\"，而是占据了一个位置——位置被填满，功能未被履行。以《工会法》第十二条、第四十二条、第四十三条为据，论证形式垄断与财政依附如何共同挤出对抗功能，并提出\\"名册化悖论\\"：清点得越清楚，越不必被召集。","date":"2026-09-24T12:00:00.000Z","series":"名与数：论权力对命名与点名的双重垄断","seriesOrder":5},"headers":[],"relativePath":"posts/2026-09-24-placeholder-union.md","filePath":"posts/2026-09-24-placeholder-union.md","lastUpdated":1790251379000}'),g={name:"posts/2026-09-24-placeholder-union.md"};function p(a,o,e,l,i,h){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="占位的工会-形式垄断、财政依附与「人民」的统计在场" tabindex="-1">占位的工会：形式垄断、财政依附与「人民」的统计在场 <a class="header-anchor" href="#占位的工会-形式垄断、财政依附与「人民」的统计在场" aria-label="Permalink to &quot;占位的工会：形式垄断、财政依附与「人民」的统计在场&quot;">​</a></h1><h3 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h3><p>本文处理一个被反复讨论却始终未获命名的现象：在平台经济中，工会既未”替代”组织，也未被组织”替代”，而是占据了一个位置——<strong>位置被填满，功能未被履行；正因为位上有人，这个位置才无法被任何其他主体填充</strong>。本文称之为”占位”。需先作概念划界：在组织社会学中，co-optation（吸收）指的是既有组织把威胁性元素纳入自身以消解其对抗性——<strong>方向是组织吸纳外部元素，与本处所述”系统用一个位置吸收掉代表功能”并不相同</strong>。本处的学名是<strong>国家法团主义</strong>（state corporatism，Schmitter）；”占位”是它在本系列中的中文工作名，不是一项新发现的理论，只是一项分析工具。</p><p>文章分四步推进。第一，以《工会法》文本为据，论证形式垄断如何被制度化：<strong>第十二条</strong>规定基层工会的建立”必须报上一级工会批准”，<strong>第十条</strong>规定”全国建立统一的中华全国总工会”、”上级工会组织领导下级工会组织”——两者合起来意味着，合法的集体行动外壳<strong>只能由上面供给，不能被下面造出来</strong>。第二，论证财政依附的结构性后果：<strong>第四十三条</strong>规定工会经费主要来自用人单位按工资总额 2% 的拨缴并在税前列支，<strong>第四十二条</strong>规定工会专职工作人员的工资、奖励、补贴”由所在单位支付”——供养工会的，正是它理论上的对手方；这使”服务”而非”对抗”成为其理性选择。第三，论证法定角色中”代表”与”维稳”的双重定位及后者的优先性：<strong>第二十八条</strong>规定工会在停工、怠工事件中应”协助……尽快恢复生产、工作秩序”，<strong>第三十二条</strong>规定工会”会同用人单位”加强对职工的思想政治引领。第四，以全总公开数据论证<strong>名册化悖论</strong>：新就业形态劳动者会员总数达 2331 万人，而《中国工运事业和工会工作”十五五”规划》对覆盖 2500 万人的算法协商所设定的代表下限是<strong>不少于 5 人</strong>，且代表由”基层工会推荐、劳动者自荐”产生、须考量”思想品德”、”优先从长期稳定活跃的劳动者中”确定。</p><p>本文的核心命题是：<strong>点名权的三个环节中，清点可以由他人完成，召集与代表不能。</strong> 工会在技术上把那个多数清点得前所未有的清楚，在程序上却未提供任何让他们自己完成召集与代表的通道——<strong>“人民”的统计在场与政治缺席因此同时发生。</strong></p><p>一处必须自限：卷二曾把这一并存升级为”<strong>反向关系</strong>“（负相关）。<strong>本文撤回该升级。</strong> 本文的观察支持”高清点＋低召集”的同时出现，<strong>不支持</strong>两者之间存在函数关系——确立反向关系需要跨案例比较（须存在”清点少而召集多”的对照群体），而本文一个对照群体也没有。本文因此把论断强度降为：<strong>在特定结构下，清点的完成会取消”由被清点者自己集合”这一程序的必要性</strong>；至于清点是否<strong>主动抑制</strong>召集，本文无材料裁定。 文章最后修正卷二提出的三问判据，并指出与米歇尔斯式寡头化的区别<strong>不在可逆性而在来源</strong>：退化型是”会员的组织”，占位型是”组织的会员”。</p><p><strong>关键词</strong>：占位；形式垄断；财政依附；不可召集性；统计在场；名册化悖论；平台劳动；集体协商</p><h3 id="一、问题的提出-一个被填满的位置" tabindex="-1">一、问题的提出：一个被填满的位置 <a class="header-anchor" href="#一、问题的提出-一个被填满的位置" aria-label="Permalink to &quot;一、问题的提出：一个被填满的位置&quot;">​</a></h3><p>卷二结尾留下一个三选一：在平台经济中，工会究竟是替代了组织，还是被组织替代了，还是两者都不是。</p><p>先排除前两项。</p><p><strong>不是”替代了组织”。</strong> 因为组织的核心功能——独立议价、对抗能力、由劳动者自身控制的议程与撤回权——并未被交付。一个不能自行成立、不能说不、说不之后不能存活的主体，没有替代组织，它替代的是组织<strong>的位置</strong>。</p><p><strong>也不是”被组织替代”。</strong> 因为自组织（陈国江的”外送江湖骑士联盟”）并非接班的候选者，而是被移除的对象。移除与接班是两回事：如果自组织能够合法存在并与之竞争，那才谈得上”替代”；而在自组织被从博弈中移除的条件下，占据位置的主体并未赢得竞争，它只是<strong>没有竞争者</strong>。</p><p>因此是第三种：<strong>占位</strong>。</p><p>这个区分不是文字游戏。它改变了对现象的全部判断方式：</p><ul><li>若理解为”替代”，则追问的是<strong>效能</strong>——它替劳动者争取到了什么？</li><li>若理解为”被替代”，则追问的是<strong>竞争</strong>——为什么它输给了自组织？</li><li>若理解为”占位”，则追问的是<strong>排他性</strong>——它占住这个位置，排除了谁？</li></ul><p>第三种问法才是本文认为正确的问法。因为前两种问法都会落入同一个陷阱：<strong>它们承认”有没有组织”是一个可以争论的问题，从而在事实上承认了位置上的那个东西就是组织。</strong> 而占位机制的精妙之处恰恰在于：它让”有没有”这个问题永远得到一个肯定的答案，从而使”是什么”这个问题永远无法被提出。</p><p><strong>一个被填满的位置，是唯一无法被要求填空的位置。</strong></p><h3 id="二、概念工具-占位——先认领它的学名-再划清它的边界" tabindex="-1">二、概念工具：占位——先认领它的学名，再划清它的边界 <a class="header-anchor" href="#二、概念工具-占位——先认领它的学名-再划清它的边界" aria-label="Permalink to &quot;二、概念工具：占位——先认领它的学名，再划清它的边界&quot;">​</a></h3><h3 id="_2-1-两个候选概念-以及为什么都不够用" tabindex="-1">2.1 两个候选概念，以及为什么都不够用 <a class="header-anchor" href="#_2-1-两个候选概念-以及为什么都不够用" aria-label="Permalink to &quot;2.1 两个候选概念，以及为什么都不够用&quot;">​</a></h3><p><strong>候选一：吸收（co-optation）。</strong> 塞尔兹尼克（Philip Selznick）在《TVA 与草根》（1949）中通过对田纳西河谷管理局的研究提出：组织面临外部威胁时，最经济的应对往往不是压制，而是<strong>把威胁的元素吸收进自身结构</strong>——给它一个位置、头衔、参与程序，在不改变权力分配的前提下消解其对抗性。</p><p>这个概念的适用是有限的，必须说清：<strong>Selznick 描述的方向是”组织吸收威胁元素”</strong>，即既存组织把外部力量拉进来；而本文描述的是**“系统用一个位置吸收掉一整项功能”**，被吸收的不是某个群体，而是”代表”这件事本身。两者方向不同。本文保留”吸收”作为谱系上的近亲，但不把它当作直接理论依据。</p><p><strong>候选二，也是学名所在：国家法团主义（state corporatism）。</strong> 施密特（Philippe Schmitter）在 1974 年的经典界定中，把法团主义定义为一种利益代表系统：其中各构成单位被组织进<strong>数量有限、单一、强制性、非竞争性、层级有序且功能分化</strong>的类别之中，它们<strong>由国家认可或许可（若非由国家创立）</strong>，并被授予在其类别内的<strong>代表权垄断</strong>，作为交换，它们在领导人选择与要求表达上<strong>接受国家的相应控制</strong>。</p><p>本文的问题，用施密特的术语说，就是一个标准的国家法团主义问题。<strong>“占位”是本文给它的中文工作名，不是一个新发现的理论。</strong> 这一点必须写明，否则本文会被误读为发明了一个概念。</p><h3 id="_2-2-为什么仍需-占位-这个工作名" tabindex="-1">2.2 为什么仍需”占位”这个工作名 <a class="header-anchor" href="#_2-2-为什么仍需-占位-这个工作名" aria-label="Permalink to &quot;2.2 为什么仍需”占位”这个工作名&quot;">​</a></h3><p>如果国家法团主义已经是现成概念，为何还要另立一词？两个理由：</p><p><strong>其一，法团主义文献给出的结论比本文温和，本文必须与之划界。</strong> 施密特及后续研究者（如对新法团主义、奥地利、新加坡、北欧模式的比较研究）反复指出：在法团主义结构下，被国家认可的代表组织<strong>可能具有实质功能</strong>——它们能参与工资协调、政策协商、福利治理，并在某些条件下为成员争取到真实收益。<strong>这与本文”占位即无功能”的判断直接冲突。</strong></p><p>本文的处理不是回避这一冲突，而是<strong>限定自己的论断范围</strong>：本文不主张法团主义结构在任何条件下都无功能，而只主张——<strong>当”代表”这一功能同时被财政依附（卷三第四节）与法定协同义务（卷三第五节）锁定时，对抗性功能会被系统性地挤出。</strong> 这是一个<strong>条件命题</strong>，不是全称命题。奥地利与新加坡的差异，恰恰说明决定结果的是这些条件，而不是法团主义结构本身。<strong>本文因此接受一个反驳自己的可能：若经验显示某法团主义结构下的工会具备稳定的对抗性功能，则本文的”占位”论断须退回到”条件不成立”，而非”结论错误”。</strong></p><p><strong>其二，法团主义概念的重心在”结构”，本文的重心在”位置的排他效果”。</strong> 施密特关心的是国家与利益组织之间的<strong>交换关系</strong>；本文关心的是这个交换一旦完成，对<strong>其他潜在主体</strong>产生的排除。前者是关系描述，后者是后果描述。</p><h3 id="_2-3-占位的三种成本优势-并附反驳" tabindex="-1">2.3 占位的三种成本优势（并附反驳） <a class="header-anchor" href="#_2-3-占位的三种成本优势-并附反驳" aria-label="Permalink to &quot;2.3 占位的三种成本优势（并附反驳）&quot;">​</a></h3><p><strong>其一，正当性成本：填位使一类批评失效，但不是全部。</strong></p><p>一个空位本身就是一种指责——”劳动者没有组织”这句话是对秩序的质疑；填上之后，<strong>这一类指责在语言层面失去着力点</strong>。但必须划清边界：填位<strong>不能</strong>使批评整体失效，只会使批评<strong>改道</strong>。实践中，被占位的组织承受着大量且常见的批评（”不履职”“二老板”“脱离会员”），这些批评从未消失。</p><p>所以本文主张的只是较弱、但可检验的一点：<strong>填位取消了”有没有”这一问，迫使一切批评转入”够不够”这一问——而”够不够”的判定权在系统内。</strong> 这是批评成本的提高，不是批评的消灭。</p><p><strong>其二，维护成本极低。</strong> 一个自下生成的组织需要被持续应对：议程不可控、领袖不可控、时机不可控。由上面供给的组织，其议程、人事与节奏在系统内可预测。<strong>不可自生的组织，按定义不会失控。</strong></p><p><strong>其三，排他性极强。</strong> 位置只有一个。填上之后，任何其他主体要进入，须先证明”现有者不合格”，而判定权同样在系统内。于是形成一个<strong>难以从内部打开的闭环</strong>：位上有人，所以位子不空；位子不空，所以无人可填。</p><p>三条合起来，占位在结构上呈现出一个可描述的特征：<strong>获得排他性的成本极低</strong>——它不需要交付任何功能，只需要保证一件事：这个位置不能空着。这是对结构属性的描述，<strong>不预设任何主体在设计它</strong>。</p><h3 id="三、机制一-形式垄断——壳不可入如何被制度化" tabindex="-1">三、机制一：形式垄断——壳不可入如何被制度化 <a class="header-anchor" href="#三、机制一-形式垄断——壳不可入如何被制度化" aria-label="Permalink to &quot;三、机制一：形式垄断——壳不可入如何被制度化&quot;">​</a></h3><p>现在把这个概念落到法条上。</p><p>《中华人民共和国工会法》（2021 年 12 月 24 日修正，主席令第 107 号，2022 年 1 月 1 日施行）提供了完整的形式垄断结构：</p><blockquote><p><strong>第十条</strong> 工会各级组织按照民主集中制原则建立。全国建立统一的中华全国总工会。……上级工会组织领导下级工会组织。<br><strong>第十二条</strong> 基层工会、地方各级总工会、全国或者地方产业工会组织的建立，<strong>必须报上一级工会批准</strong>。上级工会可以派员帮助和指导企业职工组建工会，任何单位和个人不得阻挠。</p></blockquote><p>两条合起来，有三层含义必须逐层拆开：</p><p><strong>第一层：单一制。</strong> “全国建立统一的中华全国总工会”排除了竞争性工会的存在空间。不存在两个可以互相竞争的工会，也就不存在劳动者”用脚投票”这一最朴素的问责机制。</p><p><strong>第二层：层级领导。</strong> “上级工会组织领导下级工会组织”——不是协调，不是指导，是<strong>领导</strong>。基层工会的行动空间因此由上级定义。</p><p><strong>第三层，也是最关键的一层：批准制。</strong> 基层工会的建立”必须报上一级工会批准”。这一句决定了全部。</p><p>需要精确说明它的含义，以免被过度解读。批准制<strong>不等于</strong>禁止建会——相反，同条第二句规定”上级工会可以派员帮助和指导企业职工组建工会，任何单位和个人不得阻挠”，2021 年修正又在第三条新增一款，规定”工会适应企业组织形式、职工队伍结构、劳动关系、就业形态等方面的发展变化，依法维护劳动者参加和组织工会的权利”——这一新增直接回应了新就业形态。建会是被鼓励的，入会是被保障的。</p><p><strong>但批准制确立了一件更根本的事：合法外壳的供给权在上面。</strong></p><p>劳动者可以要求建会、可以被指导建会、可以在建成后入会，但<strong>不能自行生成一个未经上一级工会批准的组织，并使之成为合法的集体行动主体</strong>。需求方有需求，供给方有权力，两者不是同一批人——这就是卷二 4.3 节”壳不可入”的完整法条依据。</p><p>于是出现一个精确的分工：</p><ul><li><strong>“参加和组织工会的权利”</strong>（第三条第一款）保障的是<strong>进入</strong>的权利；</li><li><strong>“必须报上一级工会批准”</strong>（第十二条）保留的是<strong>生成</strong>的权力。</li></ul><p>保障进入、保留生成，是形式垄断最经济的形式：<strong>入口敞开，因此没有可指责的排斥；出口在上，因此没有失控的可能。</strong> 一个只能通过被批准才能存在的主体，其存在本身就是被授予的；而被授予的东西，逻辑上可以被不授予——这不是威胁，这是产权关系。</p><p><strong>一处必须自限</strong>：本文不主张批准制在实践中”铁板一块”。上级工会对基层直选试点、行业工会联合会等形态的容忍度，在不同时期与不同地区存在波动空间，本文未对此作任何经验考察。<strong>因此本文的论断是结构性的：供给权在上一级手中，这是一个法条事实；至于该权力在多大程度上被柔性行使，本文无材料裁定，故不作”绝对不可松动”的断言。</strong></p><h3 id="四、机制二-财政依附——供养者即对手方" tabindex="-1">四、机制二：财政依附——供养者即对手方 <a class="header-anchor" href="#四、机制二-财政依附——供养者即对手方" aria-label="Permalink to &quot;四、机制二：财政依附——供养者即对手方&quot;">​</a></h3><p>如果说形式垄断解决的是”谁能存在”，那么财政结构解决的是”存在的那个会做什么”。</p><blockquote><p><strong>第四十三条</strong> 工会经费的来源：（一）工会会员缴纳的会费；（二）<strong>建立工会组织的用人单位按每月全部职工工资总额的百分之二向工会拨缴的经费</strong>；（三）工会所属的企业、事业单位上缴的收入；（四）人民政府的补助；（五）其他收入。……前款第二项规定的……拨缴的经费<strong>在税前列支</strong>。……<strong>工会经费主要用于为职工服务和工会活动。</strong><br><strong>第四十二条</strong> 用人单位工会委员会的<strong>专职工作人员的工资、奖励、补贴，由所在单位支付</strong>。社会保险和其他福利待遇等，享受本单位职工同等待遇。</p></blockquote><p>这两条放在一起，构成一个极清晰的结构：</p><p><strong>第一，主要经费来自用人单位，且由税前列支。</strong> 2% 的工资总额拨缴是工会经费的主体来源，且在税前列支——这意味着它实质上是用人单位的一项法定成本，由国家以税收减免的方式分担。<strong>供养工会的，在会计意义上是用人单位；在最终的制度意义上，是国家财政的让渡。</strong></p><p><strong>第二，工会专职人员的薪酬由所在单位支付。</strong> 这一条比 2% 更直接：一个组织的专职工作人员，其工资、奖励、补贴由该组织理论上的对手方发放，且其社保与福利”享受本单位职工同等待遇”。</p><p>必须说清楚，这不是一个<strong>腐败</strong>命题，而是一个<strong>结构</strong>命题。本文不主张、也无证据主张任何具体的工会干部因薪酬来源而放弃职责。本文主张的是：</p><blockquote><p><strong>任何组织的长期行为，都会被其供养结构所塑造。当供养者是对手方时，对抗就成了一项需要额外理由的高成本行为，而协作则成了默认选项。</strong></p></blockquote><p>这不是意志问题，是激励几何学。用卷二的术语说：<strong>这是结构性收敛，不是合谋。</strong> 不需要任何人下达指令，也不需要任何人收受贿赂——只需要让工会的人员与经费由用人单位供给，”对抗”这件事就会自动变贵。</p><p>还有一个推论值得单独列出，但<strong>必须同时给出它的反向激励，否则证据选择会偏向”对手方供养”这一符号性最强的点</strong>。</p><p><strong>正方向的绑定</strong>：2% 以”全部职工工资总额”为基数拨缴，工会经费规模与用人单位工资总额<strong>正相关</strong>。经营困难，经费减少。工会与其理论对手方的经营状况被制度性地绑定。</p><p><strong>反方向的激励（本文遗漏，必须补上）</strong>：同一基数意味着——<strong>会员涨薪，工会经费增加</strong>。若工会能推动工资上涨，它自己的可支配资源随之上升。这是一条指向对抗的激励，与”供养者即对手方”方向相反，<strong>本文不能只取其一</strong>。</p><p>两条激励同时存在，净方向取决于<strong>哪一条在实际中更强</strong>。本文的判断是：经由工资总额推动经费的路径，需要工会先完成一次成功的工资集体协商——而集体协商的对抗手段本身受第四、五节所述结构约束；相比之下，由单位稳定拨缴、税前列支的路径是<strong>自动的、无条件的、不需对抗即可获得</strong>的。<strong>因此真实情形不是”没有反向激励”，而是反向激励的兑现门槛远高于顺向激励。</strong> 这是一个可检验的判断：<strong>若能观察到工会为推动涨薪而持续对抗、且经费随之显著上升的案例，本文对净方向的判断即被削弱。</strong></p><p><strong>另有一条更常规的解释本文必须提及，以免把一切都归因于”对手方供养”</strong>：拨缴经费中相当部分由上级工会统筹，基层留成比例有限。<strong>基层工会”无为”的最直接解释，可能不是供养结构，而是经费与人事的纵向集中。</strong> 本文认为供养结构是必要条件而非充分条件，纵向集中是另一条并行机制——两者孰重，本文无材料裁定。</p><p>再向前推一步，触及平台用工的特殊性：平台用工的劳动关系认定长期悬置，而 2% 的拨缴基数是”职工工资总额”。<strong>在劳动关系未被认定的地方，经费的制度基础是空缺的。</strong> 这构成一个尖锐的错位：<strong>越是需要工会的人群，越不容易产生与之对应的工会经费。</strong> 这一点值得单独研究，本文只指出其结构位置，不作量化断言。</p><h3 id="五、机制三-法定角色的双重定位——代表与维稳-后者优先" tabindex="-1">五、机制三：法定角色的双重定位——代表与维稳，后者优先 <a class="header-anchor" href="#五、机制三-法定角色的双重定位——代表与维稳-后者优先" aria-label="Permalink to &quot;五、机制三：法定角色的双重定位——代表与维稳，后者优先&quot;">​</a></h3><p>形式垄断决定谁能存在，财政依附决定它会做什么，而法定角色决定<strong>它做这些事时的身份</strong>。</p><p>2021 年修正对<strong>第六条</strong>作了一处关键修改，在工会基本职责中增加了”<strong>竭诚服务职工群众</strong>“：</p><blockquote><p><strong>第六条</strong> 维护职工合法权益、<strong>竭诚服务职工群众</strong>是工会的基本职责。工会在维护全国人民总体利益的同时，代表和维护职工的合法权益。工会通过平等协商和集体合同制度等，<strong>推动健全劳动关系协调机制</strong>，维护职工劳动权益，<strong>构建和谐劳动关系</strong>。</p></blockquote><p>全国人大常委会法工委相关解读与媒体报道均指出，这一修改强调”<strong>维权</strong>“与”<strong>服务</strong>“并举。这一点必须被准确对待：<strong>“服务”入法本身不是贬义，它确实提升了工会在救助、帮扶、法律援助等方面的供给。</strong> 本文的论点不在价值判断，而在结构位置：</p><blockquote><p><strong>当”服务”与”维权”并列为基本职责时，工会的成功标准就多了一个不需要对抗即可达成的指标。</strong> 维权需要对手、需要冲突、需要承担冲突的代价；服务只需要递送。<strong>一个组织在有两个可选的成功指标时，会系统性地偏向成本更低的那一个。</strong> 这不是懈怠，这是理性。</p></blockquote><p>（需说明：本文<strong>不主张</strong>从条文排列顺序推出价值排序。”维权”写在”服务”之前，不能被读作维权优先——正如下文不从”协助恢复秩序”写在句末推出恢复秩序优先。条文顺序不是有效的解释依据，本文在两处一律不采用。）</p><p>更关键的是第二十八条——这是全文最需要读者逐字读的一条：</p><blockquote><p><strong>第二十八条</strong> 企业、事业单位、社会组织发生<strong>停工、怠工</strong>事件，工会应当代表职工同企业、事业单位、社会组织或者有关方面协商，反映职工的意见和要求并提出解决意见。对于职工的合理要求，企业、事业单位、社会组织应当予以解决。<strong>工会协助企业、事业单位、社会组织做好工作，尽快恢复生产、工作秩序。</strong></p></blockquote><p>本文对这一条的解读<strong>不依赖句子顺序，而依赖义务结构与触发条件</strong>——这一点必须说清，否则论证会流于修辞：</p><p><strong>其一，触发条件是事后的。</strong> 本条的全部义务以”发生停工、怠工事件”为前提。法律在这里预设了停工怠工<strong>会发生</strong>，然后只规定它<strong>发生后</strong>工会应做什么。它没有、也不可能规定工会可以<strong>组织</strong>停工怠工。<strong>一项只能在其对象已经出现之后才启动的职能，在定义上不是组织职能。</strong></p><p><strong>其二，代表职能没有对抗手段作支撑。</strong> 本条要求工会”反映职工的意见和要求并提出解决意见”，也要求用人单位”应当予以解决”——但全条<strong>未赋予工会任何在用人单位不解决时可使用的手段</strong>。一个只能提出意见、不能施加后果的代表，其意见的分量取决于对方的听取意愿。</p><p><strong>其三，也是本条真正的落点：工会被明文赋予了”协助恢复生产、工作秩序”的义务。</strong> 这不是贬义判断，而是义务陈述：在劳动者最可能形成实质议价能力的那个时刻，法律给工会设定的一项明示职责，是让这个时刻<strong>尽快结束</strong>。</p><p>三条合起来是一个可检验的结构陈述：<strong>法律给了工会”在场”的义务，没有给”对抗”的手段，并给了”平息”的职责。</strong> 用卷二的术语说：工会在这里被定位为<strong>通道</strong>而非<strong>主体</strong>——功能是让诉求被听见从而更快平息，而不是让诉求被组织从而构成持续的议价力量。</p><p>这个解读的可证伪条件也很清楚：<strong>若存在工会依据第二十八条成功阻止了一次停工怠工之外、并实际改变了结果的案例，本文的”通道”判断即被削弱。</strong></p><p>还有<strong>第三十二条</strong>，一条常被忽略但极重要的规定：</p><blockquote><p><strong>第三十二条</strong> 工会<strong>会同用人单位</strong>加强对职工的思想政治引领，教育职工以国家主人翁态度对待劳动，爱护国家和单位的财产……</p></blockquote><p>“<strong>会同用人单位</strong>“——工会的法定合作对象，明文包括用人单位本身。这在比较工会法上是罕见的表述：在多数法域，工会与雇主的关系被界定为谈判对手；而在这里，二者在”引领职工”这项职能上是<strong>协同方</strong>。</p><p>第六条、第二十八条、第三十二条合起来，勾出工会的法定角色是<strong>三重叠加</strong>：代表者、服务者、协同治理者。三重之中，只有第一重具有对抗性，而它的行使边界由后两重界定。<strong>这就是卷二”三问判据”的第二问（能否说不）在法律文本层面的答案：能，但”不”的分贝由另外两重身份决定。</strong></p><h3 id="六、机制四-功能置换——最难拒绝的那笔交易" tabindex="-1">六、机制四：功能置换——最难拒绝的那笔交易 <a class="header-anchor" href="#六、机制四-功能置换——最难拒绝的那笔交易" aria-label="Permalink to &quot;六、机制四：功能置换——最难拒绝的那笔交易&quot;">​</a></h3><p>现在处理”服务替代代表”这个核心置换。它之所以稳定，不是因为它隐蔽，而是因为它<strong>几乎不可能在道德上被拒绝</strong>。</p><p>先看服务的形态（据全国总工会公开报道，涵盖服务站点、餐食补助、移动体检、互助保障、慰问与热线等类型）。</p><p>这些是<strong>真实的、有成本的、被许多人需要的善</strong>。任何严肃的分析都必须先承认这一点，否则批判就沦为了姿态。</p><p><strong>关于本节的方法</strong>：本文在此<strong>不列举具体规模数字</strong>。理由是来源自反性——这类绩效数字<strong>全部来自被分析方自身的公开发布</strong>，无独立第三方核验；用一方自我报告的规模去论证该方”在道德上不可拒绝”，存在一个循环（若数字虚高，论证强度随之虚高），而列举本身就已经完成了规模所携带的修辞工作。</p><p>本文因此把结论限定为：<strong>无论这些服务的实际规模如何，服务这一职能在结构上具有下述三项政治功能；规模只影响强度，不影响性质。</strong> 下文三项分析均可在规模未知的条件下成立——它们依赖的是<strong>服务的形式</strong>，不是服务的数量。</p><p>问题不在这些项目好不好，而在它们的<strong>政治功能</strong>：</p><p><strong>第一，服务与权利具有不同的制度属性——这是本文能站住的表述，不涉及任何心理推断。</strong></p><p>服务权利供给方式由组织直接递送须经主张方可实现计量可计数（份数、人次、站点数）不可计数（无法统计”阻止了一次不公”）撤回由供给方决定，接受者无撤回权由主张者持有撤回与重申的机制存续条件取决于供给方的持续意愿取决于主张方的持续能力差别因此不在”服务让人感恩”（那是心理推断，本文无材料支持），而在：<strong>服务只需递送即可完成，权利必须经由一个可持续的主张—撤回—对抗机制才存在。</strong> 一个可以只靠递送完成的功能，与一个必须靠机制维持的功能，在组织的行为倾向中不可能占同等权重。</p><p><strong>须撤回的一句</strong>：本文写道”服务建立的是债务关系，不是权利关系”，并进一步推论”感激在语法上无法转化为要求”。<strong>这是心理归因，无证据支持，已撤回。</strong> 上表的制度属性分析不依赖任何关于接受者心理的假设。</p><p><strong>第二，服务是可计量的，代表权不是。</strong> 站点数量、餐食份数、体检人次——全部可以写成数字、进入考核、对外发布。而”代表权”无法计量：你无法统计”阻止了一次不公正的算法调整”。<strong>当考核体系只能计量前者时，后者就会系统性萎缩。这不是人的选择，是度量的选择。</strong></p><p><strong>第三，也是最关键的一点：服务在道德上不可拒绝。</strong> 你可以批评一个工会不敢谈判，但你很难批评一个工会送餐。<strong>谁会反对给骑手送餐？</strong> 当一个组织获得了”无人能反对”的道德地位，它就同时获得了”无人能追问”的政治地位。（此处不引用具体份数——理由见上文来源自反性警告：份数来自被分析方自报，且本节论点不依赖数量。）</p><p>这正是卷二第一节处理的”反向征用”在工会问题上的具体形态：<strong>不是禁止工会去代表，而是给工会一件更便宜、更安全、更受欢迎的事去做。</strong></p><p>而这笔交易的定价，写在<strong>第四十三条第三款</strong>里：</p><blockquote><p>工会经费<strong>主要用于为职工服务和工会活动</strong>。</p></blockquote><p>请注意这句话的分量。<strong>法律明文规定工会经费的主要用途是”服务”，而不是”谈判”，不是”组织”，不是”对抗”。</strong> 服务型工会因此不是一个实践中的偏差，也不是某届领导的路线选择，而是<strong>法定的、由经费条款锁定的组织定位</strong>。</p><p>一个由对手方供养、其经费法定用于服务的组织，去做对抗——这需要它同时违反自己的财政激励和自己的法定用途说明。<strong>它偶尔仍然会做，这值得尊敬；但不能把它设为常态期待。</strong></p><h3 id="七、名册化悖论-2331-万会员与-5-名代表" tabindex="-1">七、名册化悖论：2331 万会员与 5 名代表 <a class="header-anchor" href="#七、名册化悖论-2331-万会员与-5-名代表" aria-label="Permalink to &quot;七、名册化悖论：2331 万会员与 5 名代表&quot;">​</a></h3><p>本节兑现卷二留给本文的任务：解释统计在场与政治缺席为何<strong>同时出现</strong>。</p><h3 id="_7-1-清点的一端-全总公开数据" tabindex="-1">7.1 清点的一端：全总公开数据 <a class="header-anchor" href="#_7-1-清点的一端-全总公开数据" aria-label="Permalink to &quot;7.1 清点的一端：全总公开数据&quot;">​</a></h3><p>据全国总工会与全国人大常委会执法检查报告的公开数据：</p><p>指标数值口径来源与时点新就业形态劳动者会员总数2331 万人存量（累计在册）全总 2026 年第三季度新闻发布会2021—2025 年上半年发展新就业形态劳动者会员2095 万人增量（期内新发展，非存量）全国人大常委会工会法执法检查报告（2025 年 9 月）2021—2024 年全国新建基层工会 / 发展会员37.6 万家 / 3389.6 万人增量，且分母为全国各行业（不限于新就业形态）同上头部平台建会12 家头部平台企业地市级以上分支机构建会全覆盖机构覆盖率（非人数）全总算法与劳动规则协商15 家平台企业签订集体协议，覆盖超 2000 万人已协商覆盖人数全总（2026 年 2 月）2023 年饿了么全网集体合同覆盖 1.1 万个配送站点、超 300 万名骑手单份合同覆盖人数新华社等公开报道2026 年算法协商规划覆盖目标2500 万人规划目标值，非实测值《中国工运事业和工会工作”十五五”规划》相关报道<strong>口径说明（必读）</strong>：上表七个数字<strong>分属四种不同口径</strong>——存量、期内增量、全行业增量、规划目标值。它们不能相加、不能直接互比，也不构成一致的时间序列（时点跨 2023—2026 年）。本文把它们并置，仅用于说明<strong>清点的精度与广度</strong>，<strong>不用于任何数值推算</strong>。本文曾将 2500 万这一<strong>规划目标</strong>与实测数据排入同一逻辑，造成口径混淆，此处已单独标注。</p><p>这些数字的意义不容低估。<strong>平台劳动者在统计意义上是当代被清点得最清楚的劳动群体之一。</strong> 他们有会员数、有建会率、有覆盖率、有协商次数。作为<strong>人口</strong>，他们庞大、清晰、可加总。</p><h3 id="_7-2-召集的另一端-不少于-5-人" tabindex="-1">7.2 召集的另一端：不少于 5 人 <a class="header-anchor" href="#_7-2-召集的另一端-不少于-5-人" aria-label="Permalink to &quot;7.2 召集的另一端：不少于 5 人&quot;">​</a></h3><p>现在看另一端。据《中国工运事业和工会工作”十五五”规划》及全总权益保障部的公开说明：</p><ul><li>2026 年拟推动 **18 家重点平台（企业）**召开全平台协商会议并签订协商协议或合同；</li><li>预计覆盖 <strong>2500 万</strong>新就业形态劳动者；</li><li>明确<strong>劳动者一方协商代表不少于 5 人</strong>；</li><li>代表的产生方式：由平台企业工会，在所在地工会或相关产业工会<strong>指导下</strong>，<strong>综合考虑思想品德、岗位性质、工作年限、性别、区域分布等因素</strong>，通过<strong>基层工会推荐、劳动者自荐</strong>等方式，优先从<strong>长期稳定活跃</strong>的劳动者中确定。</li></ul><p>本文曾以”2500 万 ≥ 5 名代表”这一不等式制造对比。经核，该式<strong>不成立，已从本文删除</strong>：5 是<strong>下限</strong>，实际协商人数未知；用未知数的下限构造比例，是修辞操作，不是测量。</p><p>可核查的表述只能是下面这一句，它比不等式弱，但它是真的：</p><blockquote><p>覆盖 2500 万人（规划目标口径）的算法协商，其劳动者一方协商代表的<strong>下限由该规划设定为不少于 5 人</strong>——规划文件不是法律，此处”下限”指规划要求，不是法定标准；实际人数未见公开数据。</p></blockquote><p>真正可检验的，不是”多少人代表多少人”，而是<strong>产生方式</strong>——这一点有明文，不依赖对未知数的推测。</p><p>再读代表的产生方式，四处细节值得逐字处理：</p><ol><li><strong>“由平台企业工会……指导下”确定</strong>——产生主体与指导主体都在系统内；</li><li><strong>“综合考虑思想品德”</strong>——遴选标准含政治性条款；</li><li><strong>“基层工会推荐、劳动者自荐”</strong>——是<strong>遴选</strong>，不是<strong>选举</strong>；</li><li><strong>“优先从长期稳定活跃的劳动者中确定”</strong>——本文读作”优先选择最不可能组织对抗的人”，<strong>这是动机归因，无证据支持，已撤回</strong>。”稳定活跃”同样可以合理地读作”有经验、了解行业、能持续参会”，这是任何协商机制都会有的正常遴选偏好。</li></ol><p>可检验的表述只能是：<strong>该标准把”在现状中的稳定程度”设为优先项。</strong> 至于”稳定活跃”是否等于”更依赖现状”、进而是否等于”更不可能对抗”，是<strong>两级推断，本文只有第一级（标准文本）有依据，后两级无材料支持</strong>。本文因此只主张第一级，并把它归入 7.3 节的制度分析，不用它推断意图或心理。</p><p>第 3 点最需要说清楚，因为它与马克思在《法兰西内战》中的要求正好相反。公社设计的核心不是”选出好人”，而是<strong>随时可撤换</strong>——代表权的要害在<strong>撤回</strong>，不在<strong>遴选</strong>。遴选可以选出最优秀的人，但撤回权保证的是：被选出的任何人都必须持续面对被撤换的可能。<strong>一个只能被推荐、不能被选举、也不能被召回的代表，不是代表，是样本。</strong></p><p>“优先从长期稳定活跃者中确定”，则把遴选逻辑推到了顶点：<strong>在一个统计总体中，被优先选出的，是那些最深度嵌入现状的个体。</strong> 这一标准的<strong>效果</strong>是选出更依赖现状的人；本文不主张这是设计意图（理由见上）。但无论意图如何，其程序性质不变：<strong>这是抽样，不是授权。</strong></p><h3 id="_7-3-两种-必要性-的区分" tabindex="-1">7.3 两种”必要性”的区分 <a class="header-anchor" href="#_7-3-两种-必要性-的区分" aria-label="Permalink to &quot;7.3 两种”必要性”的区分&quot;">​</a></h3><p>现在处理卷二 5.2 节的倒挂悖论，并<strong>修正其中的一处概念滑动</strong>。</p><p>卷二说：平台劳动者被高度清点，而自我召集的通道缺位。这个描述成立。卷二进一步说两者呈”反向关系”，<strong>这一点已在上文撤回</strong>。</p><p>本文要补的是更弱、但可站住的一层：</p><blockquote><p><strong>在治理者一端，清点的完成取消了召集的程序必要性。</strong></p></blockquote><p>这里必须区分两种”必要”，卷二把它们混在一起了：</p><ul><li><strong>管理上的必要性</strong>：清点完成后，治理者已获得所需信息，因此<strong>不需要</strong>再让被治者集合一遍。这一条成立。</li><li><strong>政治上的必要性</strong>：被治者是否需要把自己集合起来以形成力量——这<strong>不因清点完成而消失</strong>。恰恰相反，被清点者若要主张什么，仍需自己集合。</li></ul><p>卷二那句”清点的完成，恰恰取消了召集的必要性”，只有在<strong>主语是治理者</strong>时才成立；若主语换成被治者，它就是错的。<strong>本文保留前者，删除后者。</strong> 修正后的命题因此是：</p><blockquote><p><strong>清点的完成，取消了”治理者需要被治者自己集合”的必要性，但没有取消、也不可能取消”被治者需要自己集合”的必要性。</strong></p></blockquote><p>所观察到的”高清点＋零召集”，与这两种必要性的不对称<strong>一致</strong>。</p><p><strong>须说明一处因果桥的缺失</strong>：必要性本身不行动——是制度在行动。严格说来，本文观察到的是”治理者不启动集合程序”与”被治者无启动通道”同时存在，<strong>至于前者是否构成后者的原因，本文无材料裁定</strong>。更稳妥的表述是：<strong>两种不对称的必要性，为”不提供集合通道”这一制度选择提供了持续的合理性；而通道的控制权在哪一方手中，才是结果差异的直接变量。</strong></p><p>这比”互为条件”弱，但它不依赖概念滑动，且可被推翻：<strong>若能观察到一个被高度清点的群体同时具备畅通的自我召集通道，则本文命题不成立。</strong></p><p>回到 2023 年饿了么那份覆盖 300 万骑手的全网集体合同。新华社报道的标题用词是”<strong>一键覆盖</strong>“。这个词比任何评论都准确：<strong>覆盖是一个技术动作，不是一次民主程序。</strong> 300 万人被覆盖了，但他们没有被召集——没有任何环节需要他们先集合、先讨论、先表决，再产生那个”是”。</p><p>这不是要否定那份合同的实质收益（”算法取中”、极端天气配送时间调整等条款确有实益）。本文要指出的是它<strong>不要求主体在场</strong>：它改善了 300 万人的条件，而这一改善的完成不需要 300 万人先成为主体。至于长期是否间接生成主体，本文无材料裁定。 这与卷二对欧盟《平台工作指令》举证责任倒置的判断完全一致——<strong>不需要主体在场就能生效的保护，也就不要求主体生产。</strong></p><h3 id="_7-4-回到卷一" tabindex="-1">7.4 回到卷一 <a class="header-anchor" href="#_7-4-回到卷一" aria-label="Permalink to &quot;7.4 回到卷一&quot;">​</a></h3><p>由此可以给整个系列的线索收口。</p><p>卷一说：批判性词汇经名词化、翻译塌缩、所指漂移、概念翻转与阵营焊合，最终空洞化为身份标记。 卷二说：这还不是终点，”人民”的最终形态不是空洞化，而是<strong>被剥夺了可召集性</strong>。 本文补充的是治理者一端的机制：<strong>清点的完成，可以取消治理者等待被治者自行集合的程序必要性。</strong></p><blockquote><p><strong>“人民”在每一个名册上都被记录，在每一个程序里都不被召集；而记录之完整，恰恰是免于被召集的理由——既然已经知道你们有多少人，又何必让你们自己数一遍。</strong></p></blockquote><p>一个空洞的词，你还可以争论它是什么意思；一个被完整清点、因而不必被召集的词，你连争论的入口都没有——<strong>因为没有任何程序要求它先被召集，才能被代表。</strong></p><h3 id="八、对称性-这不是中国独有-但有一处不同" tabindex="-1">八、对称性：这不是中国独有，但有一处不同 <a class="header-anchor" href="#八、对称性-这不是中国独有-但有一处不同" aria-label="Permalink to &quot;八、对称性：这不是中国独有，但有一处不同&quot;">​</a></h3><p>为避免本文沦为单向指控，必须给出对称图景。工会脱离会员、走向官僚化与保守化，是二十世纪劳工运动的普遍现象，不是任何单一法域的发明。</p><p><strong>其一，米歇尔斯的寡头统治铁律。</strong> 罗伯特·米歇尔斯在《政党社会学》（1911）中以德国社会民主党与其工会为材料提出：任何大规模组织，无论其纲领多么民主，都将不可避免地产生一个与会员分离的、自我维系的领袖层；组织规模越大、技术越复杂，这一层越难被替换。<strong>“组织即寡头”。</strong></p><p><strong>其二，美国的”商业工会主义”（business unionism）。</strong> 美国工会自二十世纪中叶起，大量转向以集体合同谈判与服务供给为主的模式，重心从阶级动员转向为会员争取具体条款。批评者（如后来的”新工会主义”讨论）指出，这使工会日益像一个<strong>保险与服务机构</strong>，而非社会运动。</p><p><strong>其三，日本的企业工会。</strong> 工会以企业为单位组织，与雇主的长期经营状况深度绑定，对抗性让位于协调性。这与本文第四节所述 2% 拨缴造成的绑定，在功能上高度相似。</p><p>列出这些，是为了说明：<strong>服务替代代表、领袖层脱离会员、对抗让位于协调，是工会运动的普遍熵增，不是某一制度的特有病症。</strong> 谁把这说成中国独有，谁就自动丧失了比较分析的资格。</p><p><strong>但有一处不同，必须指出，否则对称就变成了掩饰。</strong></p><p>上述三种情形，在发生学上是<strong>内生的</strong>：工会先由劳动者自下组织起来，随后在规模扩大、专业化的过程中逐渐寡头化、保守化。它们是<strong>退化</strong>——从对抗性组织退化成服务性组织。</p><p>而本文所分析的结构，在发生学上是<strong>先天的</strong>：合法外壳的供给权自始在上面（第十二条），供养关系自始指向用人单位（第四十二条、第四十三条），法定角色自始包含”会同用人单位”（第三十二条）与”恢复生产秩序”（第二十八条）。</p><h3 id="_8-1-一处必须承认的自我反驳-米歇尔斯恰恰否定程序性可逆" tabindex="-1">8.1 一处必须承认的自我反驳：米歇尔斯恰恰否定程序性可逆 <a class="header-anchor" href="#_8-1-一处必须承认的自我反驳-米歇尔斯恰恰否定程序性可逆" aria-label="Permalink to &quot;8.1 一处必须承认的自我反驳：米歇尔斯恰恰否定程序性可逆&quot;">​</a></h3><p>本文写道：”退化可以逆转——至少在理论上，会员可以通过选举、罢免、退会、另组工会来夺回组织。”<strong>这一段站不住，必须撤回。</strong></p><p>理由很简单：<strong>米歇尔斯铁律的中心论点，恰恰就是程序性可逆性的失败。</strong> 他笔下的德国社会民主党及其工会<strong>有</strong>选举、<strong>有</strong>党内民主程序、<strong>有</strong>代表大会，寡头化照样发生且稳固。用”程序存在所以可逆”去反驳米歇尔斯，是拿他的材料去否定他的结论。<strong>“理论上可逆”是可能性判断，本文直接把它当成了现实性判断。</strong></p><p>因此本节不再主张”别处可逆”。修正后的主张如下，它更弱但经得起查：</p><blockquote><p><strong>退化型与占位型的区别，不在”能否被会员推翻”，而在”会员这个身份从何而来”。</strong> 退化型工会中，会员资格先于领袖层——是先有会员的自发联合，后有从中产生的领袖；占位型结构中，组织先于会员——是先有被批准成立的组织，后有被发展入会的会员。<strong>前者是会员的组织，后者是组织的会员。</strong></p></blockquote><p>这个区别不承诺可逆性，只承诺<strong>来源</strong>。它能推出的是一个更弱的、但可检验的结论：<strong>来源不同，问责的方向不同。</strong> 会员的组织，其领袖至少在发生学上欠会员一次授权；组织的会员，其组织不欠会员任何东西——它欠的是批准它成立的那一级。</p><h3 id="_8-2-激活确有成功案例-但都发生在特定条件下" tabindex="-1">8.2 激活确有成功案例，但都发生在特定条件下 <a class="header-anchor" href="#_8-2-激活确有成功案例-但都发生在特定条件下" aria-label="Permalink to &quot;8.2 激活确有成功案例，但都发生在特定条件下&quot;">​</a></h3><p>为免本节沦为”别处也不行”的犬儒结论，必须补上反面证据：<strong>会员层激活工会并非不可能，历史上有成功案例。</strong> 美国 1930 年代的产业工会联合会（CIO）运动与 1970 年代的 rank-and-file（基层会员）运动，都是对抗性被重新激活的实例。</p><p><strong>但必须指出：这两个案例都削弱本文的论题，而本文此前未察觉。</strong></p><p><strong>其一，CIO 的主要形式不是”在既有官僚层内部激活”，而是”另立组织”。</strong> 各产业组织委员会被 AFL 开除后，另行组建了新的全国性劳联——这是<strong>用脚投票加另建</strong>的路径，不是激活既有组织。它因此不但支持不了”激活会员层”，反而<strong>支持了本系列的形式供给论</strong>：新组织之所以能成立并存活，是因为《瓦格纳法》提供了法律形式供给。<strong>这个案例是形式供给论的证据，不是激活论的证据。</strong></p><p><strong>其二，两者的共同条件恰恰是法律窗口与组织者供给。</strong> CIO 依托《瓦格纳法》的保护期；rank-and-file 运动依托 1960—70 年代的公共部门立法扩张与一批专职组织者。两条都不是”类型”变量。</p><p>由此得到的可检验命题是：</p><blockquote><p><strong>激活会员层的努力，其成败主要取决于是否存在法律保护窗口与组织者供给，而不是取决于”退化还是占位”这一类型。</strong></p></blockquote><p><strong>须标注其材料规模</strong>：这一命题由两个案例（CIO、rank-and-file）推出，n=2 不足以确立”主要取决于”这类排他性主张。它在此处的身份是<strong>可检验的假设</strong>，本文不作定论。</p><p><strong>这个命题若成立，本章”对称但有一处不同”的论题即被取消</strong>——因为决定结果的是条件，不是类型。本文接受这个后果，并在下文 8.3 与结论中据此降级。</p><h3 id="_8-3-因此-处方完全不同-必须降级" tabindex="-1">8.3 因此，”处方完全不同”必须降级 <a class="header-anchor" href="#_8-3-因此-处方完全不同-必须降级" aria-label="Permalink to &quot;8.3 因此，”处方完全不同”必须降级&quot;">​</a></h3><p>结合 8.1 与 8.2，本文把强结论降级为<strong>条件命题</strong>：</p><ul><li><strong>一项不成立的表述</strong>：”对退化，处方是激活会员；对占位，处方只能是改变供给权与供养结构——把后者当前者来医，会开出完全无效的药方。”</li><li><strong>修正后</strong>：<strong>在供给权与供养结构未变的条件下，单纯激活会员层的处方预期效果有限</strong>——因为被激活者缺乏对抗手段，且对抗的代价由其个人承担（见第九节第三问）。这一判断的可证伪条件是：<strong>若能观察到供给权未变而会员层激活仍取得实质对抗成果的案例，本文判断即被推翻。</strong></li></ul><p>“完全无效”是无证据的断言，本文不再主张。<strong>“预期效果有限”是本文能站住的强度。</strong></p><h3 id="九、三问判据-给工会量一遍" tabindex="-1">九、三问判据：给工会量一遍 <a class="header-anchor" href="#九、三问判据-给工会量一遍" aria-label="Permalink to &quot;九、三问判据：给工会量一遍&quot;">​</a></h3><p>现在用卷二第八节提出的三问判据，对本文对象作一次系统检验。</p><p><strong>第一问：能否不经许可进入？</strong>（准入）</p><p>部分成立，但需分层。</p><ul><li><strong>个体层面：是。</strong> 第三条第一款明文规定劳动者”都有依法参加和组织工会的权利”，2021 年修正新增的第二款更专门回应了新就业形态。入会在法律上是受保障的。</li><li><strong>组织层面：否。</strong> 第十二条要求基层工会的建立必须报上一级工会批准。<strong>个体可以进入一个被供给的壳，但不能自己造一个壳。</strong></li></ul><p><strong>第二问：能否说”不”？</strong>（对抗）</p><p>受限，且限制写在文本里。</p><ul><li>第二十八条：停工、怠工事件中工会的法定落点是”协助……尽快恢复生产、工作秩序”；</li><li>无罢工权的宪法与法律基础（1982 年宪法取消了 1975、1978 年宪法中的罢工自由条款）；</li><li>第六条把”构建和谐劳动关系”、”推动健全劳动关系协调机制”写入基本职责。</li></ul><p>但必须给出对称的、对它有利的证据：<strong>第二十一条</strong>规定”工会代表职工与企业……进行平等协商，依法签订集体合同。<strong>集体合同草案应当提交职工代表大会或者全体职工讨论通过</strong>“。这是一条真实的、有对抗潜力的程序规定——法律确实赋予了劳动者对集体合同的通过权。</p><p><strong>本文的质疑因此不应指向条文，而应指向条文的适用尺度</strong>：一份覆盖 300 万人的”全网集体合同”，在何种程序意义上完成了”提交……全体职工讨论通过”？新华社所用的”<strong>一键覆盖</strong>“这一表述，恰恰提示了程序的实际形态——<strong>覆盖先于讨论，或者说，覆盖取代了讨论。</strong> 这是一个可核查的、值得追问的程序问题，而不是一个立场问题。</p><p><strong>第三问：说”不”之后能否存活？</strong>（存续）</p><p>这是最弱的一环，也是决定性的一环。</p><ul><li>工会专职工作人员的工资、奖励、补贴由所在单位支付（第四十二条）——对抗的经济代价由工会人员个人承担；</li><li>协商代表由”基层工会推荐、劳动者自荐”产生，非选举产生，<strong>因此不存在”被会员召回”这道程序</strong>；</li><li>代表遴选”优先从长期稳定活跃的劳动者中确定”——被选出的，是那些最承担不起代价的人。</li></ul><p>用卷二的原话收束这一节：</p><blockquote><p><strong>牙齿不在壳里，在别处。</strong></p></blockquote><p>而卷二那句最冷的结论，在这里得到了最完整的验证：</p><blockquote><p><strong>可撤回性不仅是一种制度设计，也是一种风险分配。如果撤回的代价全部落在撤回者身上，再精巧的设计也不会被使用。</strong></p></blockquote><p>工会的问题不在于它没有设计，而在于<strong>它所有的设计，都把对抗的代价留给了最没有能力承担代价的人</strong>：专职干部（薪酬在单位手里）、协商代表（身份是推荐来的，且被要求是”稳定活跃”的）。</p><h3 id="十、结论" tabindex="-1">十、结论 <a class="header-anchor" href="#十、结论" aria-label="Permalink to &quot;十、结论&quot;">​</a></h3><p>本文的论证可压缩为五条：</p><p><strong>第一，工会在平台经济中既未替代组织，也未被组织替代，而是占位</strong>——位置被填满，功能未被履行；正因为位上有人，这个位置无法被任何其他主体填充。占位的三种成本优势（正当性成本低、维护成本低、排他性强）使它成为最优策略：<strong>它不需要交付任何功能，只需要保证这个位置不能空着。</strong></p><p><strong>第二，形式垄断由法条明文确立。</strong> 第十二条规定基层工会建立”必须报上一级工会批准”，第十条规定”全国建立统一的中华全国总工会”、”上级工会组织领导下级工会组织”。其精确含义是：<strong>保障进入，保留生成</strong>——入口敞开因此无可指责，出口在上因此不会失控。一个只能被批准才能存在的主体，其存在本身就是被授予的。</p><p><strong>第三，财政结构塑造行为倾向，但方向不是单一的。</strong> 工会经费主体来自用人单位按工资总额 2% 的拨缴并税前列支（第四十三条），专职人员工资由所在单位支付（第四十二条）——供养工会的是它理论上的对手方。</p><p>但同一基数也产生<strong>反向激励</strong>：会员涨薪，经费随之增加。<strong>两条激励同时存在</strong>，净方向取决于哪条在实际中更强。本文的判断是：经由涨薪推动经费需先完成一次成功的工资协商，门槛远高于自动拨缴；因此顺向激励占优。此外，经费的纵向统筹与基层留成比例，可能是”基层无为”的更常规解释——<strong>本文把供养结构定位为必要条件而非充分条件，不主张单因解释。</strong> 若观察到工会为推高工资而持续对抗、且经费随之显著上升的案例，本文判断即被削弱。</p><p>而第四十三条第三款”工会经费主要用于为职工服务和工会活动”，则把服务型定位写进了经费用途。</p><p><strong>第四，名册化悖论成立（论断强度已下调）：统计在场与政治缺席同时发生，且前者取消了”由被治者自己集合”的程序必要性。</strong> 新就业形态劳动者会员总数达 2331 万（存量口径），而覆盖 2500 万人（规划目标口径）的算法协商，其劳动者一方协商代表下限由规划设定为<strong>不少于 5 人</strong>（非法定标准）；代表由推荐与自荐产生、须考量”思想品德”、”优先从长期稳定活跃的劳动者中确定”。这不是代表，是抽样。<strong>点名权三环节中，只有清点被交付给了被治者之外的主体：它的完成取消了治理者对”被治者自行集合”的程序必要性，未取消——也不可能取消——被治者对召集的必要性。通道由前者控制，这就是悖论所在。</strong></p><p><strong>第五，与米歇尔斯式寡头化的区别不在可逆性，而在来源。</strong> 本文已撤回”退化可逆转、占位不可逆转”这一说法——米歇尔斯铁律的中心论点恰恰是程序性可逆的失败（德国社民党有选举、有党内民主、有代表大会，寡头化照样稳固）。修正后的区别是<strong>来源</strong>：退化型工会是<strong>会员的组织</strong>（先有会员的联合，后有从中产生的领袖）；占位型结构是<strong>组织的会员</strong>（先有被批准成立的组织，后有被发展入会的会员）。</p><p>这个区别不承诺可逆性，只承诺问责方向的差异：<strong>会员的组织，其领袖在发生学上欠会员一次授权；组织的会员，其组织不欠会员什么——它欠的是批准它成立的那一级。</strong></p><p>相应地，处方主张<strong>不分级</strong>：8.2 节已指出，会员层激活的成败主要取决于是否存在法律保护窗口与组织者供给，而不取决于”退化还是占位”这一类型。因此本文只主张较弱的一点：<strong>在供给权与供养结构未变的条件下，单纯激活会员层的预期效果有限。</strong> 该判断可被推翻——若能观察到供给权未变而会员层激活仍取得实质对抗成果的案例。</p><h3 id="系列收口" tabindex="-1">系列收口 <a class="header-anchor" href="#系列收口" aria-label="Permalink to &quot;系列收口&quot;">​</a></h3><p>回到卷一的那个语言学问题。</p><p>卷一说，批判性词汇被空心化为身份标记；卷二说，”人民”的处境不是空洞，而是不可召集；本文补充的是第三类证据：</p><blockquote><p><strong>剥夺可召集性的，正是清点本身。而清点之所以能够完成，恰恰是因为有主体占据了那个位置——它替 2331 万人报了到，于是这 2331 万人便不必再自己集合一次。</strong></p></blockquote><p>这就解释了整个系列中最难解释的那个现象：<strong>为什么在一个”人民”被引用得最频繁、被统计得最精确的体系里，”人民”反而最不可能作为主体出现。</strong></p><p>更稳妥的表述是：<strong>代表越完整，治理过程对”被治者自行集合”这一步骤的依赖就越低；名册越精确，集合在治理程序中的必要性就越弱。</strong></p><p>这里说的是治理者一端：它不再需要这一步。至于被治者一端是否”能够”被召集，那是他们的通道与能力问题，<strong>本文未测量，不作全称判断</strong>。</p><p>在卷二的案例中，被移除的那个节点所做的不是”代表”骑手，而是<strong>让逾万名骑手自己数一遍自己</strong>。至于移除的原因，本文没有材料判断，也不主张”必须”——可以陈述的只有：被移除的，是执行点数的那个节点。</p><p>一个允许被治者自己点数的系统会面临什么结果，本文同样不作预判：点出来的数字与管理名册上的那个<strong>可能一致，也可能不一致</strong>，而那次点数从未被允许完成，因此没有材料可供判断。</p><p>这一点因此是可检验的，而非警句：<strong>若某处存在被允许完成的自主点数，且结果与官方名册一致而未被干预，则本文命题被推翻。</strong></p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2086517156284477799" target="_blank" rel="noreferrer">查看原文</a></p></blockquote>',207)])])}const d=t(g,[["render",p]]);export{u as __pageData,d as default};
